import React, { Component } from "react";
import { Container, Row, Col } from "reactstrap";
import OfferSubmit from "./OfferSubmit";
import SaveItem from "./SaveItem";
import Categories from "./Categories";
import { Link } from 'react-router-dom';
import saveicon from "../img/svg/001-save-file-option.svg";
import ItemBackground from "../img/Post Box.png";
import LikeIcon from "../img/Heart- Light Grey.png";
import MessageIcon from "../img/Message- Light Grey.png";
import ShareIcon from "../img/Share- Light Grey.png";
import Constant from '../util/Constant';
import { getParameterByName } from "../util/helper";
import ItemBox from "./itemBox/ItemBox";
import { Spinner } from 'reactstrap';
import ItemService from "../services/ItemService";
import InfiniteScroll from "react-infinite-scroll-component";

class CatResults extends Component {
  constructor(props) {
    super(props);

    this.state = {
      isLoaded: false,
      isInfiniteLoaded: false,
      disableInfiniteScroll: false,
      models: [],
      category: this.props.category,
      showItem: false,
      singleResult: '',
      lastId: '',
      zipCode: this.props.zipCode || getParameterByName('zipCode'),
      distance: this.props.distance || getParameterByName('distance'),
      errorMessage: '',
      showResults: true,
      selectedItem: {},
      closed: true,
      clickToShow: false,
      showOfferSubmit: false,
      showSaveItem: false,
      token: this.props.token,
    };

    this.onItemFull = this.onItemFull.bind(this);
    this.changeCategory = this.changeCategory.bind(this);
    this.onOfferSubmit = this.onOfferSubmit.bind(this);
    this.onSaveItem = this.onSaveItem.bind(this);
    this.onCancel = this.onCancel.bind(this);
    this.onClose = this.onClose.bind(this);
    this.getItems = this.getItems.bind(this);
    this.getItemsInfinite = this.getItems.bind(this, '', true);
    this.searchBehaviorObject = ItemService.getSearchBehaviorObject();
  }

  componentDidMount() {
    const self = this;
    console.log("Mounting CatResults");
    let category = this.props.category;
    this.setState({ category });
    this.getItems();

    // Getting search behavior
    ItemService.getSearchBehaviorObject().subscribe(searchDetails => {
      if (searchDetails && searchDetails.zipCode) {
        self.setState({ zipCode: searchDetails.zipCode, distance: searchDetails.distance, models: [], lastId: '', isLoaded: false }, () => {
          self.getItems();
        });
      }
    });
  }

  /**
   * Getting the items.
   * @param {*} category The optinal category.
   */
  getItems(category = '', isInfiniteScroll = false) {
    console.log('Is infinite', isInfiniteScroll);
    this.setState({ isInfiniteLoaded: !isInfiniteScroll });
    ItemService.getAllItems(category || this.state.category, this.state.lastId, this.state.zipCode, this.state.distance)
      .then((json) => {
        if (json) {
          json.items = json.items || [];
          console.log("It worked, got the category items.", json.items);
          this.setState({
            isLoaded: true,
            isInfiniteLoaded: true,
            models: this.state.models.concat(json.items),
            lastId: json.lastId,
            disableInfiniteScroll: json.items.length === 0 ? true : false
          });
        } else {
          this.setState({
            isLoaded: isInfiniteScroll,
            isInfiniteLoaded: false,
          });
        }
      })
      .catch(error => {
        console.log(error.response);
        this.setState({ errorMessage: error.response && error.response.data ? error.response.data.message : error.message });
      });
  }

  changeCategory(cat) {
    this.setState({
      category: cat,
      showResults: false,
      disableInfiniteScroll: false
    });
    this.getItems();
  }

  onItemFull(id) {
    this.setState({
      singleResult: id,
      showItem: true,
      closed: false,
    });
  }

  onClickToShow = () => {
    const { clickToShow, showSaveItem } = this.state;
    this.setState({
      showSaveItem: false,
    });
    if (!clickToShow) {
      this.setState({
        clickToShow: true,
      });
    } else {
      this.setState({
        clickToShow: false,
      });
    }
  };

  onOfferSubmit = (id) => {
    const { showOfferSubmit, singleResult } = this.state;
    if (singleResult !== "" && singleResult !== id) {
      this.setState({
        singleResult: id,
        showOfferSubmit: true,
      });
    } else {
      if (!showOfferSubmit) {
        this.setState({
          singleResult: id,
          showOfferSubmit: true,
        });
      } else {
        this.setState({
          showOfferSubmit: false,
          singleResult: "",
        });
      }
    }
  };

  onSaveItem = (id) => {
    const { showSaveItem, singleResult, clickToShow } = this.state;
    this.setState({
      showItem: false,
      clickToShow: false,
    });

    if (singleResult !== "" && singleResult !== id) {
      this.setState({
        singleResult: id,
        showSaveItem: true,
      });
    } else {
      if (!showSaveItem) {
        this.setState({
          singleResult: id,
          showSaveItem: true,
        });
      } else {
        this.setState({
          showSaveItem: false,
          singleResult: "",
        });
      }
    }
  };

  onCancel() {
    this.setState({
      showSaveItem: false,
    });
  }

  onClose() {
    this.setState({
      showItem: false,
    });
  }

  render() {
    console.log("Save Icon:", saveicon);
    return (
      <div className="CatResults">
        <h1 style={{ paddingTop: "20px", marginBottom: "0px" }}>DO YOU HAVE</h1>
        <h5
          style={{
            fontWeight: "400",
            color: "#A9A9A9",
          }}
          className="results-sub-title"
        >
          WHAT PEOPLE ARE LOOKING FOR?
        </h5>
        <Categories />
        <hr
          style={{
            backgroundColor: "#000000",
            width: "85%",
            marginBottom: "0.5rem",
          }}
        />
        <hr
          style={{
            backgroundColor: "#000000",
            width: "70%",
            marginTop: "0rem",
          }}
        />

        <div className="categoryResults">
          {
            !this.state.isLoaded
            ? <Spinner className="block-center" style={{ width: '5rem', height: '5rem' }} />
            : <InfiniteScroll
                dataLength={this.state.models.length}
                next={this.getItemsInfinite}
                hasMore={!this.state.disableInfiniteScroll}
                loader={<Spinner className="block-center" style={{ width: '5rem', height: '5rem' }} />}
              >
                <Row style={{ margin: "0px" }}>
                  {
                    this.state.models.length > 0
                    ? this.state.models.map((model) => (
                      <Col key={model._id}>
                        <ItemBox item={model} />
                      </Col>
                    ))
                    : <div className="block-center m-40 w-100">
                        No results to show!
                      </div>
                  }
                </Row>
              </InfiniteScroll>
          }
        </div>
      </div>
    );
  }
}

export default CatResults;
