import React, { Component } from 'react';
import LoginImg from '../img/Top Bar- Gold.png';
import Login from './Login';
import UserService from '../services/UserService';
import { BiUserCircle } from "react-icons/bi";
import { BsCaretDownFill } from "react-icons/bs";

import {
  getFromStorage,
  setInStorage,
  deleteFromStorage
} from '../util/storage';

class MobileLogin extends Component {

  constructor(props) {
    super(props);

    this.state = {
      showLogin: false
    }
    this.onLoginIcon = this.onLoginIcon.bind(this);
  }

  onLoginIcon = () => {
    if (this.state.showLogin) {
      this.setState({
        showLogin: false
      })
    }
    
    this.setState({
      showLogin: true
    })
  }

  onLogout() {
    deleteFromStorage();
  }

  render() {
    const isAuth = UserService.isConnected();
    const { userName, firstName} = UserService.getUserSessionDetails() || {};

    return (
      <div className="MobileLogin" style={{paddingTop: isAuth ? '0px' : '15px'}}>
        {
          !isAuth
          ? <div className="registerText">
              <a style={{ color: '#000000', textDecoration: "none" }} href="/Register">SIGN UP</a><div className="space-break"></div>
            </div>
          : (null)
        }
        {
          (!isAuth) ? (
            <div className="mobile-login-box">
              <div className="signInText cursor-pointer" onClick={this.onLoginIcon}>
                <span
                  style={{ color: '#000000' }}>SIGN IN</span>
              </div>
              {
                this.state.showLogin ? (
                  <Login isAuth={isAuth} userName={userName} firstName={firstName} modal={true} key={Date.now()} />
                  ) : null
              }
            </div>
            ) : (null)
        }
        {
          (isAuth) ? (
            <div className="mobile-login-box">
              <p>
                <BiUserCircle className="profile-icon"/>
                <a style={{ color:'#000000' }} href="/userpanel">Welcome, {firstName}!</a><br />
                <a style={{ color:'#000000' }} href="#" onClick={this.onLogout}>Logout</a>
                {/* <BsCaretDownFill className="profile-icon"/> */}
              </p>
              <br />
            </div>
          ) : (null)
        }
      </div>
    );
  }
}

export default MobileLogin;
